c:
\begin{equation}
\label{gtl:coefficients}
 \begin{aligned}
 A_T(\mathfrak m)
 &=\sum_{\substack{\mathfrak a\mathfrak b\mid\mathfrak m\\
             (\mathfrak a,\mathfrak b)=1\\
             N\mathfrak a,N\mathfrak b\le T}}
                    \mu(\mathfrak a)\mu(\mathfrak b),\\
 c_f(\mathfrak m)
 &=f(\mathfrak m)\nu(\mathfrak m)R_{\mathfrak m}(u_0)
                                             W(N\mathfrak m/D).
 \end{aligned}
\end{equation}

\begin{equation}
\label{gtl:profile}
 \begin{aligned}
 B_W&=\|W\|_\infty,\qquad
 \widehat W(t)=\int_0^\infty W(x)x^{-it}\,\frac{dx}{x},\\
 \mathcal M(W)&=\frac1{2\pi}\int_{\mathbb R}|\widehat W(t)|\,dt.
 \end{aligned}
\end{equation}

\begin{equation}
\label{gtl:capacity}
 a=\lceil A_1\rceil,\qquad
 b=\min\{\lceil2A_1\rceil-1,\lfloor H/Nu_0\rfloor\},
 \qquad K=\sqrt b .
\end{equation}

\begin{equation}
\label{gtl:deletions}
 \begin{aligned}
 T_q&=S\cup\operatorname{supp}(\mathfrak m\mathfrak n),\\
 Q_s^{T_q}(K;\eta^2)
   &=\sum_{\substack{\mathfrak k\ {\mathrm{good},SF}\\
                   N\mathfrak k\le K,\;(\mathfrak k,T_q)=1}}
         \frac{\mu(\mathfrak k)\eta(\mathfrak k)^2}
              {(N\mathfrak k)^s},\\
 P_S(\eta)&=\sum_{\mathfrak e\mid P_S}
                   \frac{\mu(\mathfrak e)\eta(\mathfrak e)}
                        {N\mathfrak e},
 \qquad P_S=\prod_{p\in S}p .
 \end{aligned}
\end{equation}

\begin{equation}
\label{gtl:top-window}
 V=X^{1/6}/2,\qquad
 b_{\mathfrak w}=(X/N\mathfrak w)^{1/6},\qquad
 t_{\mathfrak w}=\bigl((N\mathfrak w)^{-1/6}-1/2\bigr)_+ .
\end{equation}

\begin{equation}
\label{gtl:outer-coefficient}
 \begin{aligned}
 d_\theta[f_1,f_2]
 &=\frac{\kappa_S A_1}{D}h_{AB\rho}(\mathcal O)
     c_{f_1}(\mathfrak m)\overline{c_{f_2}(\mathfrak n)}
     \frac{g(\mathfrak m)g(\mathfrak n)\epsilon(\eta)}{\sqrt F}\\
 &\quad\cdot
      \frac{\mu(\mathfrak e)\eta(\mathfrak e)}{N\mathfrak e}
                       \overline{\eta(\mathfrak w)},\qquad
 \lambda_\theta=\frac{A_1N\mathfrak w}{N\mathfrak e F}.
 \end{aligned}
\end{equation}

\begin{equation}
\label{gtl:actual-mean}
 \begin{aligned}
 \mathcal M_{\mathrm{top}}
 :=\frac{M_{\mathrm{top}}}D
 &=\sum_\theta d_\theta[A_U,A_U]
     \sum_{\substack{\mathfrak k\ {\mathrm{good},SF}\\N\mathfrak k\le K,\;(\mathfrak k,T_q)=1}}
       \frac{\mu(\mathfrak k)\eta(\mathfrak k)^2}
            {(N\mathfrak k)^2}\\
 &\quad\cdot\int_V^{b_{\mathfrak w}}
       \dot G\left(\frac{\lambda_\theta t^6}
                         {(N\mathfrak k)^2}\right)\,dt .
 \end{aligned}
\end{equation}

\begin{equation}
\label{gtl:cubic-gauss}
 \begin{aligned}
 G_{\mathfrak m}
 &=\frac1{\sqrt{N\mathfrak m}}
   \sum_{x\bmod\alpha_{\mathfrak m}}
      \chi_{3,\mathfrak m}(x)
      \exp\!\left(2\pi i\operatorname{Tr}
                   \frac{x}{\delta\alpha_{\mathfrak m}}\right),\\
 g_{\mathfrak m}(z)
 &=\overline{\chi_{3,\mathfrak m}(z)}G_{\mathfrak m}.
 \end{aligned}
\end{equation}

\begin{equation}
\label{gtl:S-factor}
 \mathcal S_{\mathfrak m,\mathfrak n,\rho}
  =\theta_S(\alpha_{\mathfrak m}\alpha_{\mathfrak n})
       \theta_q(\gamma_S)
        \frac{\tau_{\gamma_S}(\theta_S)}{\sqrt{N\mathfrak f_S}} .
\end{equation}

\begin{equation}
\label{gtl:root-cubic}
 \begin{aligned}
 \epsilon(\eta)
 &=\mathcal S_{\mathfrak m,\mathfrak n,\rho}
       \Gamma(\alpha_{\mathfrak m}\alpha_{\mathfrak n})
       \mu(\mathfrak m)\mu(\mathfrak n)
       \vartheta(\mathfrak m)\overline{\vartheta(\mathfrak n)}
       \overline{G_{\mathfrak m}}G_{\mathfrak n},\\
 \Gamma(a+b\omega)
 &=\tfrac12\{1+i^{-b}+i^a+i^{b-a}\}.
 \end{aligned}
\end{equation}

\begin{equation}
\label{gtl:ternary}
 \mu(\mathfrak m)A_T(\mathfrak m)
   =\sum_{\substack{\mathfrak a\mathfrak b\mathfrak c=\mathfrak m\\
                   N\mathfrak a,N\mathfrak b\le T}}
                                         \mu(\mathfrak c).
\end{equation}

\begin{equation}
\label{gtl:T-coefficient}
 T_U(\mathfrak z)+T_Y(\mathfrak z),\qquad
 T_L(\mathfrak z)=
       \sum_{\substack{\mathfrak b\mid\mathfrak z\\N\mathfrak b\le L}}
                                  \mu(\mathfrak z/\mathfrak b).
\end{equation}

\begin{equation}
\label{gtl:gauss-cross}
 \overline{G_{\mathfrak a\mathfrak z}}
  =\overline{G_{\mathfrak a}}\overline{G_{\mathfrak z}}
                 \chi_{3,\mathfrak a}(\alpha_{\mathfrak z}),
 \qquad(\mathfrak a,\mathfrak z)=1 .
\end{equation}

\begin{equation}
\label{gtl:linear-tail}
 \begin{split}
 \left|\sum_{\mathfrak m\ {\mathrm{good},SF}}
  \frac{\mu(\mathfrak m)(A_U-A_Y)(\mathfrak m)
          \overline{G_{\mathfrak m}}\lambda(\mathfrak m)}
       {\sqrt{N\mathfrak m}}W(N\mathfrak m/D)\right|\\
 \ll_\epsilon\mathcal M(W)D^\epsilon
                   \{D^{1/3}+\sqrt{D/Y}\}.
 \end{split}
\end{equation}

\begin{equation}
\label{gtl:long-residual}
 \mu(\mathfrak m)A_Y(\mathfrak m)
  =\sum_{\substack{\mathfrak a\mathfrak b\mathfrak c=\mathfrak m\\
                   N\mathfrak a,N\mathfrak b\le Y}}\mu(\mathfrak c),
 \qquad N\mathfrak c\ge D/Y^2\ge D^{3/4}.
\end{equation}

\begin{equation}
\label{gtl:discrete-support}
 \mathcal T_X=
 \{(\mathfrak w,\mathfrak s):N\mathfrak w<64,\ \mathfrak s\ {\mathrm{good}},
       \ V<N\mathfrak s\le2V,\ N\mathfrak w(N\mathfrak s)^6\le X\}.
\end{equation}

\begin{equation}
\label{gtl:discrete-coefficient}
 \begin{aligned}
 \widetilde d_\theta[f_1,f_2]
 &=\frac{A_1}{D}h_{AB\rho}(\mathcal O)
       c_{f_1}(\mathfrak m)\overline{c_{f_2}(\mathfrak n)}
          \frac{\epsilon(\eta)}{\sqrt F}\\
 &\quad\cdot\frac{\mu(\mathfrak e)\eta(\mathfrak e)}{N\mathfrak e}
                                  \overline{\eta(\mathfrak w)} .
 \end{aligned}
\end{equation}

\begin{equation}
\label{gtl:direct-prefix}
 \begin{aligned}
 \mathcal P_X[f_1,f_2]
 &=\sum_{\theta\in\widetilde\Theta}\widetilde d_\theta[f_1,f_2]
     \sum_{\mathfrak k}
           \frac{\mu(\mathfrak k)\eta(\mathfrak k)^2}
                {(N\mathfrak k)^2}\\
 &\quad\cdot
 \sum_{\substack{\mathfrak s:\;(\mathfrak w,\mathfrak s)\in\mathcal T_X}}
   \bar\rho(\mathfrak s)^6
       \mathbf1_{(\mathfrak s,\mathfrak m\mathfrak n)=1}
       \dot G\left(\frac{\lambda_\theta(N\mathfrak s)^6}
                              {(N\mathfrak k)^2}\right).
 \end{aligned}
\end{equation}

\begin{equation}
\label{gtl:ray-count}
 \begin{aligned}
 N_{\psi,q}(t)
 &:=\sum_{\substack{\mathfrak s\ {\mathrm{good}}\\
                    N\mathfrak s\le t,\;(\mathfrak s,\mathfrak q)=1}}
                                                  \psi(\mathfrak s)\\
 &=\delta_\psi\kappa_S g(\mathfrak q)t+E_{\psi,q}(t),\\
 |E_{\psi,q}(t)|
 &\ll_{S,\psi}t^{1/3}
                  \sum_{\mathfrak d\mid\mathfrak q}(N\mathfrak d)^{-1/3}
 \ll_\epsilon D^\epsilon t^{1/3},
 \qquad N\mathfrak q\le4D^2 .
 \end{aligned}
\end{equation}

\begin{equation}
\label{gtl:full-IE}
 N_{\psi,q}(t)
  =\sum_{\mathfrak d\mid\mathfrak q}
       \mu(\mathfrak d)\psi(\mathfrak d)
                       N_{\psi,1}(t/N\mathfrak d).
\end{equation}

\begin{equation}
\label{gtl:Stieltjes-scale}
 c=\frac{A_1N\mathfrak hN\mathfrak r}
              {(N\mathfrak k)^2N\mathfrak e F}.
\end{equation}

\begin{equation}
\label{gtl:frequency-sum}
 \frac1{\sqrt{N\mathfrak m}}\sum_{x\bmod\alpha_{\mathfrak m}}
       \chi_{3,\mathfrak m}(x)
        \exp\!\left(2\pi i\operatorname{Tr}
                   \frac{zx}{\delta\alpha_{\mathfrak m}}\right)
       =\overline{\chi_{3,\mathfrak m}(z)}G_{\mathfrak m}.
\end{equation}

\begin{equation}
\label{gtl:Jacobi-identification}
 \begin{aligned}
 J_q(\theta_q,\theta_q^2)
     &=j(\mathfrak m)\overline{j(\mathfrak n)},\\
 j(\mathfrak m)/\sqrt{N\mathfrak m}
     &=\mu(\mathfrak m)\vartheta(\mathfrak m),
       \qquad \vartheta=\Psi/\sqrt N,\quad
                        \operatorname{cond}\Psi=(2\delta).
 \end{aligned}
\end{equation}

\begin{equation}
\label{gtl:cubic-CRT-root}
 \begin{aligned}
 \chi_{3,\mathfrak m}(\alpha_{\mathfrak n})
   &=\chi_{3,\mathfrak n}(\alpha_{\mathfrak m}),\\
 \tau_q(\theta_q^2)/\sqrt{Nq}
   &=G_{\mathfrak m}\overline{G_{\mathfrak n}}.
 \end{aligned}
\end{equation}

\begin{equation}
\label{gtl:frequency-transport}
 \begin{aligned}
 \eta(\mathfrak k^2)
   &=\theta_S(\alpha_{\mathfrak k})^2
        \chi_{3,\mathfrak m}(\alpha_{\mathfrak k})
        \overline{\chi_{3,\mathfrak n}(\alpha_{\mathfrak k})},\\
 \overline{G_{\mathfrak m}}G_{\mathfrak n}
        \chi_{3,\mathfrak m}(z)
        \overline{\chi_{3,\mathfrak n}(z)}
   &=\overline{g_{\mathfrak m}(z)}g_{\mathfrak n}(z).
 \end{aligned}
\end{equation}

\begin{equation}
\label{gtl:matched-moments}
 m_j=\int_0^\infty v^jG(v)\,dv,\qquad
 I_j(\mathfrak w)
   =\frac{b_{\mathfrak w}^{6j+1}-V^{6j+1}}{6j+1}
   =\int_V^{b_{\mathfrak w}}t^{6j}\,dt .
\end{equation}

\begin{equation}
\label{gtl:finite-selectors}
 \begin{aligned}
 \mathbf1_{[\mathfrak m]=A}
   &=\frac1{|\mathcal C|}\sum_{\chi\in\widehat{\mathcal C}}
           \overline{\chi(A)}\chi([\mathfrak m]),\\
 \Gamma(x\alpha_{\mathfrak n})
   &=\sum_{\chi\in\widehat{\mathcal H}}a_{\chi,\mathfrak n}\chi(x),
       \qquad \sum_\chi|a_{\chi,\mathfrak n}|\le\sqrt{12}.
 \end{aligned}
\end{equation}

\begin{equation}
\label{gtl:two-boxes}
 \begin{aligned}
 &\mathbf1_{N\mathfrak a,N\mathfrak b\le U}
       -\mathbf1_{N\mathfrak a,N\mathfrak b\le Y}\\
 &\quad=\mathbf1_{Y<N\mathfrak a\le U,\;N\mathfrak b\le U}
       +\mathbf1_{N\mathfrak a\le Y,\;Y<N\mathfrak b\le U}.
 \end{aligned}
\end{equation}

\begin{equation}
\label{gtl:grouped-form}
 \begin{split}
 \sum_{\substack{\mathfrak a,\mathfrak z\ {\mathrm{good},SF}\\
                         Y<N\mathfrak a\le U}}
 &\frac{\overline{G_{\mathfrak a}}\lambda(\mathfrak a)}
             {\sqrt{N\mathfrak a}}\,
   \frac{\overline{G_{\mathfrak z}}\lambda(\mathfrak z)
                         [T_U(\mathfrak z)+T_Y(\mathfrak z)]}
             {\sqrt{N\mathfrak z}}\\
 &\quad\cdot\chi_{3,\mathfrak a}(\alpha_{\mathfrak z})
                         W(N\mathfrak aN\mathfrak z/D).
 \end{split}
\end{equation}

\mathbf1_{(\mathfrak a\mathfrak z,\mathfrak n)=1}
 =\mathbf1_{(\mathfrak a,\mathfrak n)=1}
  \mathbf1_{(\mathfrak z,\mathfrak n)=1}

\begin{equation}
\label{gtl:dyadic-L2}
 \begin{aligned}
 \sum_{N\mathfrak a\asymp A}
   \left|\frac{\overline{G_{\mathfrak a}}\lambda(\mathfrak a)}
                    {\sqrt{N\mathfrak a}}\right|^2&\ll1,\\
 \sum_{N\mathfrak z\asymp Z}
   \left|\frac{\overline{G_{\mathfrak z}}\lambda(\mathfrak z)
                    [T_U(\mathfrak z)+T_Y(\mathfrak z)]}
                    {\sqrt{N\mathfrak z}}\right|^2
                                                    &\ll_\epsilon D^\epsilon .
 \end{aligned}
\end{equation}

\begin{equation}
\label{gtl:Mellin-separation}
 W(N\mathfrak aN\mathfrak z/D)
  =\frac1{2\pi}\int_{\mathbb R}\widehat W(t)D^{-it}
                  (N\mathfrak a)^{it}(N\mathfrak z)^{it}\,dt .
\end{equation}

\begin{equation}
\label{gtl:other-column}
 \sum_{\mathfrak n\ {\mathrm{original}}}
       \frac{|A_T(\mathfrak n)W(N\mathfrak n/D)|}
